import{_ as e,o as n,c as s,a2 as t}from"./chunks/framework.D8Tso2Ul.js";const m=JSON.parse('{"title":"Arquitectura Multi-tenant","description":"","frontmatter":{},"headers":[],"relativePath":"arquitectura/multi-tenant.md","filePath":"arquitectura/multi-tenant.md"}'),i={name:"arquitectura/multi-tenant.md"};function o(l,a,r,d,p,c){return n(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="arquitectura-multi-tenant" tabindex="-1">Arquitectura Multi-tenant <a class="header-anchor" href="#arquitectura-multi-tenant" aria-label="Permalink to &quot;Arquitectura Multi-tenant&quot;">​</a></h1><p>Build &amp; Serve es un <strong>SaaS multi-tenant</strong>: múltiples empresas (tenants) usan la misma infraestructura, pero sus datos están completamente aislados entre sí.</p><h2 id="principio-de-aislamiento" tabindex="-1">Principio de aislamiento <a class="header-anchor" href="#principio-de-aislamiento" aria-label="Permalink to &quot;Principio de aislamiento&quot;">​</a></h2><p>Toda tabla operacional incluye <code>tenantId</code>, ya sea como atributo o como parte de la Partition Key. <strong>Nunca</strong> se realiza un Scan sin filtro de tenant.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PersonasTable    PK = TENANT#{tenantId}   ← aislamiento en la propia key</span></span>
<span class="line"><span>ObrasTable       PK = TENANT#{tenantId}</span></span>
<span class="line"><span>DocumentosTable  PK = TENANT#{tenantId}</span></span>
<span class="line"><span>ActivitiesTable  tenantId como atributo + GSI tenantId-index</span></span></code></pre></div><h2 id="fuente-del-tenantid" tabindex="-1">Fuente del tenantId <a class="header-anchor" href="#fuente-del-tenantid" aria-label="Permalink to &quot;Fuente del tenantId&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Regla crítica de seguridad</p><p>El <code>tenantId</code> se extrae <strong>siempre del JWT</strong>, nunca del body del request. Esto previene que un cliente acceda a datos de otro tenant manipulando los parámetros enviados.</p></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. La persona inicia sesión → el JWT incluye su tenantId</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>2. Cada request envía el JWT en Authorization: Bearer</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>3. El Lambda decodifica el JWT y obtiene el tenantId</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>4. Todas las queries se filtran por ese tenantId</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>5. El body del request NUNCA es fuente de tenantId</span></span></code></pre></div><h2 id="gsis-cross-tenant-controlados" tabindex="-1">GSIs cross-tenant controlados <a class="header-anchor" href="#gsis-cross-tenant-controlados" aria-label="Permalink to &quot;GSIs cross-tenant controlados&quot;">​</a></h2><p>Algunos índices son cross-tenant por diseño, pero el Lambda valida la coincidencia:</p><table tabindex="0"><thead><tr><th>GSI</th><th>Uso</th><th>Validación</th></tr></thead><tbody><tr><td><code>personaId-index</code></td><td>Lookup directo de persona (verificación de firmas, login por token)</td><td>El Lambda confirma el tenant</td></tr><tr><td><code>email-index</code></td><td>Login (el email puede existir en varios tenants)</td><td>Se valida que el tenantId del JWT coincida</td></tr></tbody></table><h2 id="el-superadmin-tenant-0" tabindex="-1">El superadmin (tenant-0) <a class="header-anchor" href="#el-superadmin-tenant-0" aria-label="Permalink to &quot;El superadmin (tenant-0)&quot;">​</a></h2><p>El <code>tenant-0</code> está reservado para el <strong>superadmin</strong>, con acceso cross-tenant para soporte y administración de la plataforma. Es la única excepción al aislamiento estricto.</p><h2 id="jerarquia-de-entidades" tabindex="-1">Jerarquía de entidades <a class="header-anchor" href="#jerarquia-de-entidades" aria-label="Permalink to &quot;Jerarquía de entidades&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tenant (empresa cliente)</span></span>
<span class="line"><span>  ├── Obra ──┬── Documentos</span></span>
<span class="line"><span>  │          ├── Actividades</span></span>
<span class="line"><span>  │          └── Incidentes</span></span>
<span class="line"><span>  └── Persona ──┬── Firmas</span></span>
<span class="line"><span>                └── Asignaciones</span></span></code></pre></div><ul><li>Un <strong>tenant</strong> tiene muchas obras y muchas personas.</li><li>Una <strong>obra</strong> agrupa documentos, actividades e incidentes.</li><li>Una <strong>persona</strong> puede estar asignada a varias obras (<code>obraIds</code>) y genera firmas y asignaciones.</li></ul><h2 id="personalizacion-por-tenant" tabindex="-1">Personalización por tenant <a class="header-anchor" href="#personalizacion-por-tenant" aria-label="Permalink to &quot;Personalización por tenant&quot;">​</a></h2><p>Cada tenant configura su propia experiencia:</p><ul><li><strong>Módulos activos</strong> (<code>settings.modulosActivos</code>): venta por módulos.</li><li><strong>Reglas SST</strong> (<code>reglas.fasesObligatorias</code>): qué fases del DS 44 aplican.</li><li><strong>Preferencias UI</strong>: colores, logo, timezone, idioma, formato de fecha.</li></ul><p>Ver <a href="/manual/modulos/tenants.html">Tenants</a> y <a href="/manual/arquitectura/base-de-datos.html">Base de datos</a>.</p>`,20)])])}const h=e(i,[["render",o]]);export{m as __pageData,h as default};
